<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Auto‑Pilot Cave Runner</title>
<style>
  body {margin:0;overflow:hidden;background:#000;}
  canvas {display:block;}
  #dist {position:absolute;top:10px;left:10px;color:#0f0;font:20px monospace;}
</style>
</head>
<body>
<div id="dist">0 m</div>
<canvas id="c"></canvas>
<script>
(() => {
  const canvas = document.getElementById('c');
  const ctx = canvas.getContext('2d');
  const W = canvas.width = window.innerWidth;
  const H = canvas.height = window.innerHeight;
  const SPEED = 2;                 // pixels per frame the cave moves left
  const GAP = 140;                 // vertical gap for the ship
  const SHIP_X = 100;              // fixed horizontal position of ship
  const ship = {y: H/2, vy:0};
  const distEl = document.getElementById('dist');
  let distance = 0;

  // Cave shape stored as arrays of top and bottom y‑coordinates for each column
  const cols = Math.ceil(W / SPEED) + 2; // enough columns to fill screen
  const top = new Array(cols);
  const bottom = new Array(cols);
  let base = H/3;               // starting ceiling height
  const maxBase = H - GAP - 50;
  const minBase = 50;

  // Initialise cave columns with a smooth random walk
  for(let i=0;i<cols;i++){
    base += (Math.random()*2-1)*3;               // small random delta
    if(base>maxBase) base=maxBase;
    if(base<minBase) base=minBase;
    top[i] = base;
    bottom[i] = base + GAP;
  }

  function addColumn(){
    // generate next column and push to arrays, discarding the leftmost one
    base += (Math.random()*2-1)*3;
    if(base>maxBase) base=maxBase;
    if(base<minBase) base=minBase;
    top.push(base);
    bottom.push(base+GAP);
    top.shift();
    bottom.shift();
  }

  function drawCave(){
    ctx.fillStyle = '#222';
    // top ceiling
    ctx.beginPath();
    ctx.moveTo(0,0);
    for(let i=0;i<top.length;i++){
      ctx.lineTo(i*SPEED, top[i]);
    }
    ctx.lineTo(W,0);
    ctx.closePath();
    ctx.fill();
    // bottom floor
    ctx.beginPath();
    ctx.moveTo(0,H);
    for(let i=0;i<bottom.length;i++){
      ctx.lineTo(i*SPEED, bottom[i]);
    }
    ctx.lineTo(W,H);
    ctx.closePath();
    ctx.fill();
  }

  function drawShip(){
    const shipSize = 12;
    ctx.fillStyle = '#ff0';
    ctx.beginPath();
    ctx.moveTo(SHIP_X, ship.y);
    ctx.lineTo(SHIP_X-shipSize, ship.y+shipSize);
    ctx.lineTo(SHIP_X+shipSize, ship.y+shipSize);
    ctx.closePath();
    ctx.fill();
  }

  function updateShip(){
    // find column index that corresponds to the ship's X position
    const idx = Math.floor(SHIP_X / SPEED);
    const targetY = (top[idx] + bottom[idx]) / 2;
    // simple proportional controller
    ship.vy += (targetY - ship.y) * 0.06;
    ship.vy *= 0.94;           // damping
    ship.y += ship.vy;
    // keep inside canvas (optional: could detect crash)
    if(ship.y < 0) ship.y = 0;
    if(ship.y > H) ship.y = H;
  }

  function loop(){
    ctx.clearRect(0,0,W,H);
    // scroll cave
    for(let i=0;i<top.length;i++){
      top[i] -= SPEED;
      bottom[i] -= SPEED;
    }
    // when first column is off‑screen, generate a new one
    if(top[0] <= -SPEED) addColumn();
    drawCave();
    updateShip();
    drawShip();
    distance += SPEED * 0.05; // arbitrary scaling to metres
    distEl.textContent = Math.floor(distance) + " m";
    requestAnimationFrame(loop);
  }

  // Resize handling
  window.addEventListener('resize',()=>{
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
  });

  loop();
})();
</script>
</body>
</html>
```

The script continuously scrolls a procedurally generated cave while a simple autonomous controller steers the ship toward the gap’s centre, updating a distance counter as it moves.
